package com.procurement.invoice.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity@Table(name="invoice_history")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class InvoiceHistory{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="invoice_id",nullable=false)private Invoice invoice;@Column(nullable=false)private String action;@Enumerated(EnumType.STRING)private InvoiceStatus oldStatus;@Enumerated(EnumType.STRING)private InvoiceStatus newStatus;@Column(length=500)private String remarks;@Column(nullable=false)private LocalDateTime performedAt;@PrePersist void pre(){if(performedAt==null)performedAt=LocalDateTime.now();}}
